      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "guanidine-containing CNS penetrants"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C09"],
      "decision_effect": "strengthened",
      "direction": "contradictory",
      "family": "polar-substituted cyclic amines with poor BBB penetration"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C08"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "cyclic tertiary amine CNS penetrants"
    }
  ],
  "revision_action": "initial"
}

